('84000000-0000-4000-8000-000000000001','demo-seed','DO','Directeur des opérations','Garantir la capacité de delivery, la rentabilité opérationnelle et la bonne exécution des projets.','Direction générale', '["Directeur des opérations","Directeur delivery"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Garantir la capacité de delivery, la rentabilité opérationnelle et la bonne exécution des projets.',TRUE),
('84000000-0000-4000-8000-000000000002','demo-seed','DT','Directeur technique','Définir la stratégie technique, garantir la cohérence des architectures et développer les compétences d''ingénierie.','Direction générale', '["CTO","Directeur ingénierie"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Définir la stratégie technique, garantir la cohérence des architectures et développer les compétences d''ingénierie.',TRUE),
('84000000-0000-4000-8000-000000000003','demo-seed','CDP','Chef de projet','Livrer le projet conformément au périmètre, aux engagements, aux coûts, aux délais et au niveau de qualité convenus.','Directeur des opérations ou sponsor', '["Project Manager","Delivery Manager"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Livrer le projet conformément au périmètre, aux engagements, aux coûts, aux délais et au niveau de qualité convenus.',TRUE),
('84000000-0000-4000-8000-000000000004','demo-seed','POBA','Responsable produit et exigences','Transformer les besoins utilisateurs et métier en exigences priorisées, cohérentes, vérifiables et acceptées.','Chef de projet ou sponsor produit', '["Product Owner","Business Analyst","Analyste fonctionnel"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Transformer les besoins utilisateurs et métier en exigences priorisées, cohérentes, vérifiables et acceptées.',TRUE),
('84000000-0000-4000-8000-000000000005','demo-seed','ARCH','Architecte logiciel et système','Définir une architecture cible cohérente, sécurisée, évolutive et réalisable répondant aux exigences fonctionnelles et non fonctionnelles.','Directeur technique', '["Architecte solution","Solution Architect"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Définir une architecture cible cohérente, sécurisée, évolutive et réalisable répondant aux exigences fonctionnelles et non fonctionnelles.',TRUE),
('84000000-0000-4000-8000-000000000006','demo-seed','TL','Responsable développement','Organiser la réalisation logicielle et garantir la qualité technique, la cohérence du code et la progression de l''équipe.','Directeur technique ou architecte', '["Tech Lead","Lead Developer"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Organiser la réalisation logicielle et garantir la qualité technique, la cohérence du code et la progression de l''équipe.',TRUE),
('84000000-0000-4000-8000-000000000007','demo-seed','DEV','Ingénieur développement logiciel','Concevoir, développer, tester unitairement et maintenir des composants logiciels conformes aux exigences et aux règles d''ingénierie.','Responsable développement', '["Développeur logiciel","Software Engineer"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Concevoir, développer, tester unitairement et maintenir des composants logiciels conformes aux exigences et aux règles d''ingénierie.',TRUE),
('84000000-0000-4000-8000-000000000008','demo-seed','IVV','Ingénieur intégration, vérification et validation','Démontrer par des activités planifiées et traçables que la solution intégrée respecte les exigences et répond à l''usage attendu.','Responsable IVV ou chef de projet', '["Ingénieur IVV","IVV Engineer","Integration & Verification Engineer"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Démontrer par des activités planifiées et traçables que la solution intégrée respecte les exigences et répond à l''usage attendu.',TRUE),
('84000000-0000-4000-8000-000000000009','demo-seed','QUAL','Responsable qualité logiciel','Définir et faire appliquer le dispositif qualité du projet et apporter une assurance objective sur la conformité des livrables et des processus.','Directeur des opérations ou directeur technique', '["Responsable qualité","Software Quality Manager"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Définir et faire appliquer le dispositif qualité du projet et apporter une assurance objective sur la conformité des livrables et des processus.',TRUE),
('84000000-0000-4000-8000-000000000010','demo-seed','DEVOPS','Ingénieur DevOps et mise en production','Automatiser la construction, les déploiements et l''exploitation technique afin de fournir des environnements fiables, reproductibles et observables.','Responsable développement ou opérations', '["DevOps Engineer","Release Engineer","SRE"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Automatiser la construction, les déploiements et l''exploitation technique afin de fournir des environnements fiables, reproductibles et observables.',TRUE),
('84000000-0000-4000-8000-000000000011','demo-seed','SYS','Ingénieur systèmes et intégration','Assurer l''interopérabilité et le bon fonctionnement de la solution dans son environnement cible et avec les systèmes tiers.','Architecte ou responsable développement', '["Ingénieur intégration système","System Engineer"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Assurer l''interopérabilité et le bon fonctionnement de la solution dans son environnement cible et avec les systèmes tiers.',TRUE),
('84000000-0000-4000-8000-000000000012','demo-seed','UX','Designer UX/UI','Concevoir des parcours et interfaces accessibles, cohérents et efficaces, fondés sur les usages et les retours utilisateurs.','Responsable produit et exigences', '["UX Designer","UI Designer","Product Designer"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Concevoir des parcours et interfaces accessibles, cohérents et efficaces, fondés sur les usages et les retours utilisateurs.',TRUE),
('84000000-0000-4000-8000-000000000013','demo-seed','SEC','Ingénieur sécurité applicative','Intégrer la sécurité dans le cycle de développement et réduire les risques sur les applications, données et infrastructures.','Directeur technique ou RSSI', '["AppSec Engineer","Référent cybersécurité projet"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Intégrer la sécurité dans le cycle de développement et réduire les risques sur les applications, données et infrastructures.',TRUE),
('84000000-0000-4000-8000-000000000014','demo-seed','DATA','Ingénieur données et bases de données','Concevoir et maintenir les modèles, traitements et stockages de données fiables, performants et sécurisés.','Architecte logiciel et système', '["Data Engineer","Database Engineer","DBA"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Concevoir et maintenir les modèles, traitements et stockages de données fiables, performants et sécurisés.',TRUE),
('84000000-0000-4000-8000-000000000015','demo-seed','SM','Facilitateur agile','Faciliter la collaboration et l''amélioration continue de l''équipe en assurant la fluidité des pratiques agiles adaptées au contexte.','Chef de projet ou responsable d''équipe', '["Scrum Master","Agile Coach"]'::jsonb,DATE '2026-11-18','1.0','Référentiel de démonstration','À valider par la direction','Faciliter la collaboration et l''amélioration continue de l''équipe en assurant la fluidité des pratiques agiles adaptées au contexte.',TRUE)
