('88000000-0000-4000-8000-000000000002','demo-seed',(SELECT id FROM job_functions WHERE code='DT'),'ACT-01','Stratégie technique et gouvernance','["Définir les orientations technologiques et principes d''architecture","Valider les choix techniques structurants et les dérogations","Garantir sécurité, maintenabilité, performance et dette technique","Organiser les compétences, communautés techniques et revues","Arbitrer les risques techniques majeurs et la trajectoire technologique"]'::jsonb,1),
('88000000-0000-4000-8000-000000000003','demo-seed',(SELECT id FROM job_functions WHERE code='CDP'),'ACT-01','Pilotage de projet','["Cadrer objectifs, périmètre, livrables, hypothèses et critères de succès","Construire et maintenir planning, budget, charges et plan de ressources","Animer gouvernance, comités, décisions et communication des parties prenantes","Piloter risques, problèmes, changements, dépendances et actions","Coordonner les phases conception, réalisation, IVV, recette et mise en production","Organiser clôture, transfert au support et retour d''expérience"]'::jsonb,1),
('88000000-0000-4000-8000-000000000004','demo-seed',(SELECT id FROM job_functions WHERE code='POBA'),'ACT-01','Produit et exigences','["Recueillir et analyser besoins, irritants et contraintes métier","Définir vision produit, parcours, cas d''usage et priorités","Rédiger exigences, user stories, règles de gestion et critères d''acceptation","Maintenir traçabilité entre besoins, exigences, conception et tests","Préparer et arbitrer le backlog avec les parties prenantes","Organiser démonstrations, validation métier et gestion des évolutions"]'::jsonb,1),
('88000000-0000-4000-8000-000000000005','demo-seed',(SELECT id FROM job_functions WHERE code='ARCH'),'ACT-01','Architecture et conception','["Analyser contraintes, exigences non fonctionnelles et systèmes existants","Définir architecture fonctionnelle, applicative, données et déploiement","Produire dossiers d''architecture, vues, interfaces et décisions techniques","Évaluer solutions, composants, technologies et risques d''intégration","Définir principes de résilience, sécurité, performance et observabilité","Accompagner les équipes et vérifier la conformité de la réalisation"]'::jsonb,1),
('88000000-0000-4000-8000-000000000006','demo-seed',(SELECT id FROM job_functions WHERE code='TL'),'ACT-01','Conduite technique du développement','["Décomposer la conception en composants et travaux réalisables","Répartir les travaux et accompagner les développeurs","Définir standards de code, branches, revues et intégration continue","Réaliser les revues techniques et traiter les risques de conception","Suivre qualité du code, dette technique, sécurité et performance","Préparer les versions et coordonner la résolution des anomalies"]'::jsonb,1),
('88000000-0000-4000-8000-000000000007','demo-seed',(SELECT id FROM job_functions WHERE code='DEV'),'ACT-01','Développement logiciel','["Analyser les spécifications et clarifier les cas limites","Concevoir et implémenter composants, API, interfaces et traitements","Écrire tests unitaires et tests de composants automatisés","Effectuer revues de code et appliquer les standards de développement","Diagnostiquer et corriger anomalies, vulnérabilités et régressions","Documenter les composants et contribuer à l''intégration continue"]'::jsonb,1),
('88000000-0000-4000-8000-000000000008','demo-seed',(SELECT id FROM job_functions WHERE code='IVV'),'ACT-01','Intégration, vérification et validation','["Élaborer stratégie, plan et procédures d''intégration et de test","Préparer environnements, jeux de données et configurations de test","Intégrer composants, systèmes, interfaces et dépendances","Exécuter tests fonctionnels, techniques, non-régression et bout en bout","Enregistrer anomalies, preuves, résultats et couverture de tests","Produire rapports de vérification, validation et recommandations de livraison"]'::jsonb,1),
('88000000-0000-4000-8000-000000000009','demo-seed',(SELECT id FROM job_functions WHERE code='QUAL'),'ACT-01','Management de la qualité','["Établir plan qualité projet, référentiels et critères d''acceptation","Définir jalons qualité, revues, audits et points de contrôle","Vérifier la traçabilité exigences-conception-code-tests-livraison","Suivre non-conformités, dérogations, actions correctives et préventives","Analyser indicateurs qualité, tendances et causes racines","Préparer avis qualité et contribuer aux décisions de passage de jalon"]'::jsonb,1),
('88000000-0000-4000-8000-000000000010','demo-seed',(SELECT id FROM job_functions WHERE code='DEVOPS'),'ACT-01','Industrialisation et exploitation','["Construire et maintenir pipelines CI/CD et chaînes de livraison","Gérer environnements, infrastructure as code, secrets et configurations","Automatiser packaging, déploiements, migrations et retours arrière","Mettre en place supervision, logs, métriques, alertes et sauvegardes","Contribuer à la disponibilité, capacité, performance et reprise","Préparer runbooks, transfert au support et suivi post-déploiement"]'::jsonb,1),
('88000000-0000-4000-8000-000000000011','demo-seed',(SELECT id FROM job_functions WHERE code='SYS'),'ACT-01','Systèmes et interfaces','["Analyser interfaces, protocoles, flux et contraintes d''environnement","Configurer et intégrer systèmes, middleware, réseaux et services","Définir contrats d''interface, formats, gestion des erreurs et reprise","Diagnostiquer incidents d''intégration et problèmes de compatibilité","Réaliser tests de connectivité, charge, robustesse et résilience","Documenter configurations, dépendances et procédures d''exploitation"]'::jsonb,1),
('88000000-0000-4000-8000-000000000012','demo-seed',(SELECT id FROM job_functions WHERE code='UX'),'ACT-01','Expérience utilisateur','["Conduire recherches utilisateurs et analyser les besoins d''usage","Modéliser parcours, scénarios, personas et architecture de l''information","Produire wireframes, prototypes et maquettes d''interface","Définir composants, règles ergonomiques et cohérence visuelle","Organiser tests utilisateurs et intégrer les retours","Vérifier accessibilité, responsive design et cohérence avec le produit"]'::jsonb,1),
('88000000-0000-4000-8000-000000000013','demo-seed',(SELECT id FROM job_functions WHERE code='SEC'),'ACT-01','Sécurité du produit','["Analyser menaces, risques, exigences et données sensibles","Définir contrôles de sécurité et exigences de conception","Accompagner pratiques de développement sécurisé et gestion des secrets","Organiser analyses de vulnérabilités et tests de sécurité","Suivre corrections, dérogations et risques résiduels","Contribuer à homologation, conformité et réponse aux incidents"]'::jsonb,1),
('88000000-0000-4000-8000-000000000014','demo-seed',(SELECT id FROM job_functions WHERE code='DATA'),'ACT-01','Données et persistance','["Concevoir modèles conceptuels, logiques et physiques de données","Définir schémas, migrations, index, contraintes et politiques de rétention","Développer flux d''ingestion, transformation et échanges de données","Garantir intégrité, qualité, traçabilité et protection des données","Optimiser performances, sauvegardes, restauration et disponibilité","Documenter dictionnaires, contrats et dépendances de données"]'::jsonb,1),
('88000000-0000-4000-8000-000000000015','demo-seed',(SELECT id FROM job_functions WHERE code='SM'),'ACT-01','Animation et amélioration continue','["Préparer et faciliter rituels et ateliers d''équipe","Rendre visibles avancement, obstacles, dépendances et décisions","Aider à clarifier et découper les éléments du backlog","Favoriser coopération, autonomie et résolution collective","Mesurer flux, prévisibilité et amélioration de l''équipe","Accompagner l''adaptation des pratiques au contexte projet"]'::jsonb,1)
